// Les deux sources documentaires ANNUELLES du dispositif, déclarées ici :
// la page d'index stable, le motif du nom de fichier, et la règle qui relie
// le millésime de l'édition à la période de données qu'elle porte.
//  - Convention patronale (H2, la même extraction sert H11) : l'édition N
//    recense l'année N — période = millésime.
//  - CCFA (A1) : l'édition N publie les années N-2 et N-1 — période (l'année
//    récente, la convention de la file) = millésime - 1.
// Même doctrine qu'ACEA : détecter n'est pas lire. Le veilleur constate
// qu'une édition NOUVELLE existe et l'inscrit en file au statut
// « a_verifier » — la vérification nominative et l'extraction restent
// humaines et multi-modèles (§ 10.4).
return [
  { json: {
    indicator_id: 'H2', geo: 'CH',
    page: 'https://cpih.ch/statistiques/',
    motif: 'Recensement[^"]*\\.pdf',
    base: 'https://cpih.ch/',
    periode_depuis_millesime: 0,
    libelle: 'Convention patronale (recensement horloger)'
  } },
  { json: {
    indicator_id: 'A1', geo: 'WORLD',
    page: 'https://ccfa.fr/analyses-et-statistiques/',
    motif: 'CCFA[^"]*FR[^"]*\\.pdf',
    base: 'https://ccfa.fr/',
    periode_depuis_millesime: -1,
    libelle: 'CCFA (annuaire de l\'industrie automobile)'
  } },
];

// Pour chaque source : le document le plus récent de la page est-il une
// édition que la file ne connaît pas encore ?
const sources = $('Cibler les éditions attendues').all().map(x => x.json);
const reponses = $input.all();
const sorties = [];
reponses.forEach((rep, i) => {
  const s = sources[i];
  const page = String(rep.json.body ?? rep.json.data ?? '');
  const statutHttp = rep.json.statusCode ?? 0;
  if (statutHttp >= 400 || !page) {
    sorties.push({ json: { ...s, verdict: 'page_injoignable', http: statutHttp } });
    return;
  }
  const re = new RegExp('href="([^"]*' + s.motif + ')"', 'gi');
  const liens = [...page.matchAll(re)].map(m => m[1]);
  if (!liens.length) {
    sorties.push({ json: { ...s, verdict: 'aucun_document', http: statutHttp } });
    return;
  }
  // Le millésime se lit dans le NOM DE FICHIER, jamais dans le chemin :
  // l'URL CCFA contient le répertoire de téléversement (/2026/06/…), qui a
  // fait naître une fausse « édition 2026 » au premier run. Constaté, corrigé.
  const avecMillesime = liens.map(u => {
    const nomFichier = u.split('/').pop();
    return { u, an: Math.max(0, ...[...nomFichier.matchAll(/20(\d{2})/g)].map(m => 2000 + Number(m[1]))) };
  });
  avecMillesime.sort((a, b) => b.an - a.an);
  const { u, an } = avecMillesime[0];
  let url = u.replace(/&amp;/g, '&');
  if (url.startsWith('//')) url = 'https:' + url;
  else if (url.startsWith('/')) url = s.base.replace(/\/$/, '') + url;
  else if (!/^https?:/i.test(url)) url = s.base + url;
  const periode = String(an + s.periode_depuis_millesime);
  sorties.push({ json: { ...s, verdict: 'document_present', millesime: an, periode, url_document: url, http: statutHttp } });
});
return sorties;

// Bilan lisible du run : ce qui a été vu, ce qui a été inscrit.
const verdicts = $('Décider des inscriptions').all().map(x => x.json);
const inscrits = $('Insérer si édition nouvelle').isExecuted
  ? $('Insérer si édition nouvelle').all().filter(x => x.json.doc_id !== undefined).length
  : 0;
const parties = verdicts.map(v =>
  v.verdict === 'document_present'
    ? `${v.indicator_id} : édition ${v.millesime} vue (période ${v.periode})`
    : `${v.indicator_id} : ${v.verdict}`);
return [{ json: {
  run_id: $('Ouvrir le run').first().json.run_id,
  note: 'Veille documentaire annuelle (CP, CCFA) : ' + parties.join(' ; ') + '. ' + inscrits + ' inscription(s) nouvelle(s).'
} }];
